use std::{fs, io::Write, path::Path};
use vw_pdf::{PdfCancellation, PdfLimits, embed_pdf_copy_metadata, verify_pdf_copy_metadata};
fn fixture() -> Vec<u8> {
    let objects: [&[u8]; 4] = [b"<< /Type /Catalog /Pages 2 0 R >>", b"<< /Type /Pages /Count 1 /Kids [3 0 R] >>", b"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 10 10] /Contents 4 0 R >>", b"<< /Length 0 >>\nstream\nendstream"];
    let mut bytes=b"%PDF-1.7\n".to_vec();let mut offsets=Vec::new();
    for (index,object) in objects.iter().enumerate(){offsets.push(bytes.len());writeln!(bytes,"{} 0 obj",index+1).unwrap();bytes.extend_from_slice(object);bytes.extend_from_slice(b"\nendobj\n");}
    let xref=bytes.len();writeln!(bytes,"xref\n0 5\n0000000000 65535 f ").unwrap();
    for at in offsets{writeln!(bytes,"{at:010} 00000 n ").unwrap();}
    write!(bytes,"trailer\n<< /Size 5 /Root 1 0 R >>\nstartxref\n{xref}\n%%EOF\n").unwrap();bytes
}
fn main()->Result<(),Box<dyn std::error::Error>> {
    let root=std::env::args_os().nth(1).ok_or("output required")?;let root=Path::new(&root);
    let limit=PdfLimits{input_bytes:1024*1024,output_bytes:1024*1024,memory_bytes:32*1024*1024,..PdfLimits::default()};
    for (name,ending) in [("lf"," \n"),("crlf","\r\n"),("cr"," \r")] {
        let text=String::from_utf8(fixture())?;let mut bytes=text.replace(" n \n",&format!(" n{ending}")).replace(" f \n",&format!(" f{ending}")).into_bytes();
        let original=blake3::hash(&bytes).to_hex().to_string();
        let metadata=format!(r#"{{"schema_version":1,"host_seq":18446744073709551615,"state_hash":"{}","revision":"r18446744073709551615-abababab","source_asset":"{original}","capture_session":"018bcfe5-6800-7000-8000-000000000001","frame_id":18446744073709551615}}"#,"ab".repeat(32));
        for round in 1..=2 {
            embed_pdf_copy_metadata(&mut bytes,&metadata,limit,&PdfCancellation::default())?;
            verify_pdf_copy_metadata(&bytes,&metadata,limit.output_bytes,&PdfCancellation::default())?;
            fs::write(root.join(format!("{name}-{round}.pdf")),&bytes)?;
            fs::write(root.join(format!("{name}-{round}.expected.json")),&metadata)?;
        }
    }
    Ok(())
}
